logger = logging.getLogger(__name__)


llm = Gemini3Flash()

# First, create the index with proper mappings
index_name = "guidelines"
    
async def guidelines_analysis(queries, ctx=None, iit_protocol="", test=False):
    queries = [q for q in queries if q and q.strip()]
    if not queries:
        logger.warning("[guidelines_analysis] All queries were empty/None, skipping embedding and returning empty result.")
        return []
    vectors = [get_embedding(q) for q in queries]
        
    # Ping ES first before doing the search
    es_client = Elasticsearch(hosts=settings.NOAH_ELASTICSEARCH_URL, basic_auth=(settings.NOAH_ELASTICSEARCH_USERNAME, settings.NOAH_ELASTICSEARCH_PASSWORD))

    try:
        ret = []
        max_attempts = 3
        backoff = 1
        last_exc = None
        all_hits = []
        # search with both query and indication vectors and corresponding texts
        for vector, text in zip(vectors, queries):
            resp = None
            for attempt in range(1, max_attempts + 1):
                try:
                    resp = es_client.search(
                        index=index_name,
                        size=40,
                        query={
                            "bool": {
                                "must": {"match": {"title_cn": text}},
                                "filter": [
                                    {"term": {"cn_file_flg.keyword": "Y"}},
                                    {"exists": {"field": "pages"}},
                                    {"exists": {"field": "toc"}}
                                ],
                                "should": [
                                    {"match": {"title_cn": {"query": "CSCO", "boost": 100}}}
                                ]
                            }
                        },
                        knn={
                            "field": "title_cn_vector",
                            "query_vector": vector,
                            "k": 40,
                            "num_candidates": 80,
                            "filter": [
                                {"term": {"cn_file_flg.keyword": "Y"}},
                                {"exists": {"field": "pages"}},
                                {"exists": {"field": "toc"}}
                            ]
                        },
                    )
                    all_hits.extend(resp.get("hits", {}).get("hits", []))
                    break
                except Exception as e:
                    last_exc = e
                    print(f"Elasticsearch search attempt {attempt} failed: {e}")
                    # try to reinitialize client before next attempt
                    if attempt < max_attempts:
                        await asyncio.sleep(backoff)
                        backoff *= 2
            else:
                # all attempts failed; propagate the last exception to be handled by outer except
                raise last_exc

        # deduplicate hits by source id (or ES _id) and build result items
        seen = set()
        resp_hits = []
        for h in all_hits:
            src = h.get('_source', {})
            gid = src.get('id') or h.get('_id')
            if gid in seen:
                continue
            seen.add(gid)
            resp_hits.append(h)

        for hit in resp_hits:
            item = {}
            for key in ['id', 'pages', 'toc', 'title_cn']:
                item[key] = hit['_source'][key]
            ret.append(item)
        print("Search returned", len(resp_hits), "guidelines")
    except Exception as e:
        print("Elasticsearch search failed:", e)
        return None
    if test:
        return ret
        
    guideline_sections = await select_guidelines(queries[0], ret, iit_text=iit_protocol)

    analysis_prompt = f"""请根据提供的相关临床<指南章节>和<IIT研究方案>的详细信息，分析、检查这些指南章节是否能够反驳IIT研究方案的必要性和创新性。
    <IIT研究方案>
    {iit_protocol}
    </IIT研究方案>
    
    <指南章节>
    {guideline_sections}
    </指南章节>
    
    如适用、具体评估以下几点：
    1. 研究方案与指南的一致性与偏差分析：分析IIT研究方案的设计是否与指南章节中的推荐实践保持一致，或者是否存在显著偏差。评估这些偏差是否合理且有助于推进临床实践，还是会削弱研究方案的有效性。
    2. 创新性：评估IIT研究方案是否引入了指南章节中未涵盖的新方法、新疗法或新手段。如果指南提供了IIT研究方案中对应内容正面或者反面的的明确建议，这意味着该研究方案在这些内容上是没有创新性的。
    3. 必要性：判断指南章节是否表明IIT研究方案所解决的临床问题已经由现有指南给出了充分的解答。如果指南提供了IIT研究方案中对应内容的明确建议，这意味着该研究方案是不必要的。

    请注意：
    指南的内容应作为循证的权威依据，如IIT方案涉及内容在指南章节中已有明确建议，则应考虑反驳创新性以及必要性。

    请结合指南和研究方案的具体内容，提供详细的分析。"""
                
    anaylsis_result = await llm(user_prompt=analysis_prompt, temperature=0)
    print("Analysis Result:", anaylsis_result[:200])
    ctx.clinical_guidance_result = anaylsis_result
    await write_iit_context(ctx)
    return anaylsis_result


